import sys

def find_earliest_takeoff(n, s, landings):
    def time_to_minutes(h, m):
        return h * 60 + m

    def minutes_to_time(minutes):
        return minutes // 60, minutes % 60

    # Check if takeoff can be inserted before the first landing
    first_landing = time_to_minutes(landings[0][0], landings[0][1])
    if first_landing >= s + 1:
